ai['result'] = record._daadit_claude_design_fetch(project_url=_url)

aid = record.id
if aid not in (10, 15):
    ai['result'] = {'ok': False, 'error': 'SCOPE-GUARD: deze tool is voor Penny (content) en Mark (marketing).'}
else:
    try:
        _tpl = template
    except Exception:
        _tpl = ''
    try:
        _sub = subline
    except Exception:
        _sub = ''
    try:
        _pid = post_id
    except Exception:
        _pid = 0
    ai['result'] = record._daadit_render_template_visual(headline=headline, subline=_sub or '', post_id=_pid or 0, template=_tpl or '')
